namespace Ordering;

/// <summary>Applies tier, override and channel adjustments to an order subtotal.</summary>
public sealed class PricingRules
{
    private const decimal WholesaleFactor = 0.95m;
    private const decimal LargeOrderThreshold = 500m;
    private const decimal LargeOrderDiscount = 10m;

    public decimal ApplyAdjustments(Order order, CustomerTier tier)
    {
        var subtotal = CalculateSubtotal(order);

        if (tier == CustomerTier.Blocked)
            return 0m;

        var adjusted = ApplyTier(subtotal, tier);
        adjusted = ApplyOverride(adjusted, order.DiscountOverride);
        adjusted = ApplyLargeOrderDiscount(adjusted, subtotal);
        adjusted = ApplyChannelAdjustment(adjusted, order.Channel);

        return Math.Max(0m, adjusted);
    }

    private static decimal CalculateSubtotal(Order order) =>
        order.Lines.Sum(line => line.UnitPrice * line.Quantity);

    private static decimal ApplyTier(decimal amount, CustomerTier tier) =>
        tier == CustomerTier.Wholesale ? amount * WholesaleFactor : amount;

    private static decimal ApplyOverride(decimal amount, decimal? value) =>
        value is > 0m ? amount - value.Value : amount;

    private static decimal ApplyLargeOrderDiscount(decimal amount, decimal subtotal) =>
        subtotal > LargeOrderThreshold ? amount - LargeOrderDiscount : amount;

    private static decimal ApplyChannelAdjustment(decimal amount, OrderChannel channel) =>
        channel switch
        {
            OrderChannel.Phone => amount + 2m,
            OrderChannel.Marketplace => amount * 1.02m,
            _ => amount
        };
}
